@import 'c/rlySharedStyles';

:host {
    --rr-muted: #5c5c5c;
    --rr-link: #0176d3;
    --rr-warn: #8c4b02;
    --rr-warn-2: #fef1cd;
    display: block;
}
.rr-pk { margin-top: 12px; border: 1px solid #e5e5e5; border-radius: 4px; background: #fff; padding: 12px 14px; display: flex; flex-direction: column; gap: 8px; }
.rr-pk-head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.rr-grow { flex: 1 1 auto; min-width: 0; }
.rr-pk-scroll { overflow-x: auto; max-width: 100%; }
.rr-pk-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.rr-pk-table th, .rr-pk-table td { padding: 8px 10px; text-align: left; border-bottom: 1px solid #f0f0f0; vertical-align: middle; white-space: nowrap; }
.rr-pk-table thead th { font-size: 11px; font-weight: 700; text-transform: uppercase; color: var(--rr-muted); background: #fafafa; }
.rr-pk-name { font-weight: 400; }
.rr-pk-raise th { font-weight: 700; font-size: 12px; }
.rr-mono { font-family: Menlo, Consolas, monospace; font-size: 12px; }
.rr-tag { display: inline-block; font-size: 11px; font-weight: 700; padding: 2px 9px; border-radius: 10px; white-space: nowrap; border: 1px solid transparent; }
.rr-tag-ok { background: #ebf7e6; color: #2e844a; }
.rr-tag-odd { background: #fef1cd; color: #8c4b02; }
.rr-tag-none { background: #f3f3f3; color: #444; }
.rr-tag-hint { font-weight: 400; color: var(--rr-muted); }
.rr-tag-off { background: #f3f3f3; color: #5c5c5c; text-decoration: line-through; }
.rr-tag-on { background: #eef4ff; color: #014486; }
.rr-tchip { cursor: pointer; font: inherit; font-size: 11px; font-weight: 700; padding: 2px 10px; border-radius: 12px; border: 1px solid #c9c9c9; background: #fff; color: #0176d3; }
.rr-tag.rr-tchip { border-color: transparent; }
.rr-tag.rr-tchip:hover, .rr-tchip:hover { border-color: #0176d3; }
.rr-tchip-on { background: #0176d3; border-color: #0176d3; color: #fff; }
.rr-tchip:disabled { cursor: default; opacity: 0.6; }
.rr-tchip:focus-visible { outline: 2px solid #0176d3; outline-offset: 1px; }
.rr-pb { padding-bottom: 4px; margin: 0; }
